head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07340";
scwin.form = null;
scwin.dts_List = null;
scwin.dts_SearchLeadComMbrNo = null;
scwin.maxLenCheckVars = undefined;
scwin.maxLenCheckNames = undefined;
scwin.maxLenCheckMax = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            const resultLen = $c.util.getComponent('dlt_resultList').getRowCount();
            for (let i = 0; i < resultLen; i++) {
                if (i < (resultLen - 1)) {
                    if (scwin.form.pershrInvstSaleTotDsp[i] == null) {

                    } else {

                    }
                }
            }
        } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldstf07340' }); }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07340.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldstf07340: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07340' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07340' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07340' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.dts_SearchLeadComMbrNo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_SearchLeadComMbrNo')) : $c.util.getComponent('dts_SearchLeadComMbrNo');
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07340.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07340.btn_print_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_List
 * @description script dts List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_List = async function () {
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, LEADCOM_MBR_NO"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, LEADCOM_MBR_NO", unresolved: "query_param:SCREN_ID,SCREN_PROCES_TP_CD,LEADCOM_MBR_NO" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/konex/InvstgAssgn.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07340.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name tx_script_dts_SearchLeadComMbrNo
 * @description script dts Search Lead Com Mbr No 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_SearchLeadComMbrNo = async function () {
    $c.util.getComponent("dma_scriptDts_SearchLeadComMbrNoReq").set("For", "R");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_ID,SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_SearchLeadComMbrNo",
        method: "post",
        action: "/konex/InvstgAssgn.do",
        ref: "dma_scriptDts_SearchLeadComMbrNoReq",
        target: "dts_SearchLeadComMbrNo=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_SearchLeadComMbrNo_onloaderror'] === 'function') ? scwin['dts_SearchLeadComMbrNo_onloaderror'] : (typeof scwin['dts_SearchLeadComMbrNo_onfail'] === 'function') ? scwin['dts_SearchLeadComMbrNo_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_SearchLeadComMbrNo_onloadcompleted'] === 'function') ? scwin['dts_SearchLeadComMbrNo_onloadcompleted'] : ((typeof scwin['dts_SearchLeadComMbrNo_onsuccess'] === 'function') ? scwin['dts_SearchLeadComMbrNo_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_SearchLeadComMbrNo'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07340.tx_script_dts_SearchLeadComMbrNo" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_resultList_fmt_invstDd
 * @description grd result List fmt invst Dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_invstDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bzProcsNo") ?? '') : '');
        if (v !== 'SUMPART') { return String((dl && dl.getCellData ? dl.getCellData(r, "invstDd") : '') ?? ''); }
        if (v === 'SUMPART') { return "소계"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.invstDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_resultList_fmt_column3
 * @description grd result List fmt column3 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_column3 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "invstChgTpCd") ?? '') : '');
        if (v === '1') { return "최초"; }
        if (v === '2') { return "증가"; }
        if (v === '3') { return "감소"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.column3" }); return String(data ?? ''); }
};

/**
 * @method
 * @name loadCapital
 * @description load Capital 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} clmInstSeq clmInstSeq
 * @param {String} comNm comNm
 * @param {String} invstChgTpCd invstChgTpCd
 * @param {String} invstDd invstDd
 * @param {*} invstSaleShrs invstSaleShrs
 * @param {*} pershrInvstSaleAmt pershrInvstSaleAmt
 * @param {String} stkNm stkNm
 * @param {*} incdecRsn incdecRsn
 * @returns {void}
 * @hidden N
 */
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent("comNm").setValue(comNm);
    (((scwin.form.invstChgTpCd) && (scwin.form.invstChgTpCd).setValue) ? (scwin.form.invstChgTpCd).setValue(invstChgTpCd) : void 0);
    $c.util.getComponent("invstDd").setValue($c.date.dateUnFormat(invstDd));
    scwin.form.invstSaleShrs.value = $c.num.formatNumber(invstSaleShrs);
    scwin.form.pershrInvstSaleAmt.value = $c.num.formatNumber(pershrInvstSaleAmt);
    (((scwin.form.stkNm) && (scwin.form.stkNm).setValue) ? (scwin.form.stkNm).setValue(stkNm) : void 0);
    (((scwin.form.incdecRsn) && (scwin.form.incdecRsn).setValue) ? (scwin.form.incdecRsn).setValue(incdecRsn) : void 0);
};

/**
 * @method
 * @name setDataMergeDate
 * @description set Data Merge Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataMergeDate = function () {
    /* empty */
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    scwin.form = (document.prelistEtcForm || { elements: [] });
};
